      const headers=rows[0].map(normalizeHeader);const aliases={matricule:['matricule','numero','numero_eleve','id_eleve'],firstName:['prenom','first_name','firstname'],lastName:['nom','last_name','lastname'],className:['classe','class','class_name','niveau'],guardianName:['parent','nom_parent','tuteur','responsable','guardian_name'],guardianPhone:['telephone','telephone_parent','tel','phone','guardian_phone']};const indexes={};for(const [key,names] of Object.entries(aliases))indexes[key]=headers.findIndex(h=>names.includes(h));if(indexes.firstName<0||indexes.lastName<0)return json(res,400,{error:'Colonnes obligatoires : prénom et nom'});
